import json
import random

def make_entry(instruction, thinking_parts, code):
    thinking = ""
    for i, part in enumerate(thinking_parts, 1):
        thinking += f"{i}. {part}\n"
    output = thinking + "\n" + code + "\n\n开发完成！该网页所有功能均已实现，可以直接在浏览器中运行使用。"
    return {"instruction": instruction, "input": "", "output": output}

