    ["创建4x4网格布局", "初始化时随机在两个格子生成2或4", "处理上下左右滑动，实现数字移动和合并", "每次移动后随机生成一个新数字", "相同数字合并翻倍，分数累加", "达到2048显示胜利，无法移动则失败"],
    '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>2048</title><style>*{margin:0;padding:0;box-sizing:border-box}body{background:#faf8ef;display:flex;flex-direction:column;align-items:center;padding:20px;font-family:Arial}h1{font-size:60px;color:#776e65}.hdr{width:340px;display:flex;justify-content:space-between;margin-bottom:15px}.sc{background:#bbada0;color:#fff;padding:8px 15px;border-radius:5px;text-align:center}.sc span{display:block;font-size:22px;font-weight:bold}.btn{background:#8f7a66;color:#fff;border:none;padding:10px 20px;border-radius:5px;cursor:pointer;font-weight:bold;font-size:16px}#g{background:#bbada0;border-radius:6px;padding:10px;display:grid;grid-template-columns:repeat(4,70px);gap:10px}.c{width:70px;height:70px;background:rgba(238,228,218,.35);border-radius:3px;display:flex;align-items:center;justify-content:center;font-weight:bold;font-size:35px}.t2{background:#eee4da;color:#776e65}.t4{background:#ede0c8;color:#776e65}.t8{background:#f2b179;color:#fff}.t16{background:#f59563;color:#fff}.t32{background:#f67c5f;color:#fff}.t64{background:#f65e3b;color:#fff}.t128{background:#edcf72;color:#fff;font-size:30px}.t256{background:#edcc61;color:#fff;font-size:30px}.t512{background:#edc850;color:#fff;font-size:30px}.t1024{background:#edc53f;color:#fff;font-size:25px}.t2048{background:#edc22e;color:#fff;font-size:25px}</style></head><body><h1>2048</h1><div class="hdr"><div style="display:flex;gap:10px"><div class="sc">分数<span id="sc">0</span></div><div class="sc">最高<span id="bs">0</span></div></div><button class="btn" onclick="init()">新游戏</button></div><div id="g"></div><script>let gr,sc=0,bs=localStorage.getItem("best2048")||0;const g=document.getElementById("g");document.getElementById("bs").textContent=bs;function init(){gr=Array(4).fill().map(()=>Array(4).fill(0));sc=0;document.getElementById("sc").textContent=sc;addT();addT();render()}function addT(){const e=[];for(let i=0;i<4;i++)for(let j=0;j<4;j++)if(!gr[i][j])e.push({i,j});if(e.length){const[p]=e;gr[p.i][p.j]=Math.random()<.9?2:4}}function render(){g.querySelectorAll(".c").forEach(c=>c.remove());for(let i=0;i<4;i++)for(let j=0;j<4;j++){const v=gr[i][j];const d=document.createElement("div");d.className="c"+(v?" t"+v:"");d.textContent=v||"";g.appendChild(d)}}document.addEventListener("keydown",e=>{let m=false;if(e.key==="ArrowLeft"){for(let i=0;i<4;i++){let ln=gr[i].filter(v=>v);for(let j=0;j<ln.length-1;j++)if(ln[j]&&ln[j]===ln[j+1]){ln[j]*=2;sc+=ln[j];ln.splice(j+1,1)}while(ln.length<4)ln.push(0);gr[i]=ln;m=true}}else if(e.key==="ArrowRight"){for(let i=0;i<4;i++){let ln=gr[i].filter(v=>v).reverse();for(let j=0;j<ln.length-1;j++)if(ln[j]&&ln[j]===ln[j+1]){ln[j]*=2;sc+=ln[j];ln.splice(j+1,1)}while(ln.length<4)ln.push(0);gr[i]=ln.reverse();m=true}}if(m){addT();render();document.getElementById("sc").textContent=sc;if(sc>bs){bs=sc;localStorage.setItem("best2048",bs);document.getElementById("bs").textContent=bs}if(gr.some(r=>r.some(v=>v===2048)))alert("你赢了!")}});e.preventDefault()});init();</script></body></html>'
