    '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>倒计时</title><style>*{margin:0;padding:0;box-sizing:border-box}body{display:flex;align-items:center;justify-content:center;min-height:100vh;background:linear-gradient(135deg,#667eea,#764ba2);font-family:Arial}.box{text-align:center;background:#fff;padding:40px;border-radius:20px;box-shadow:0 20px 60px rgba(0,0,0,.3)}.pr{position:relative;width:280px;height:280px;margin:0 auto 25px}svg{transform:rotate(-90deg)}circle{fill:none;stroke-width:10}.bg{stroke:#eee}.fg{stroke:#667eea;stroke-linecap:round;transition:stroke-dashoffset 1s linear}.tm{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:50px;font-weight:bold;color:#333}.btns{display:flex;gap:10px;justify-content:center;margin-bottom:15px}button{padding:10px 22px;border:none;border-radius:20px;cursor:pointer;font-weight:bold}.st{background:#667eea;color:#fff}.pa{background:#f39c12;color:#fff}.rs{background:#e74c3c;color:#fff}.pre{display:flex;gap:8px;justify-content:center;flex-wrap:wrap}.pre button{padding:8px 14px;background:#eee;color:#333;font-size:13px}</style></head><body><div class="box"><div class="pr"><svg width="280" height="280"><circle class="bg" cx="140" cy="140" r="120"/><circle class="fg" id="fg" cx="140" cy="140" r="120"/></svg><div class="tm" id="tm">05:00</div></div><div class="btns"><button class="st" onclick="st()">开始</button><button class="pa" onclick="pa()">暂停</button><button class="rs" onclick="rs()">重置</button></div><div class="pre"><button onclick="set(60)">1分</button><button onclick="set(300)">5分</button><button onclick="set(600)">10分</button><button onclick="set(1500)">25分</button></div></div><script>let tot=300,rem=tot,tid,run;const C=2*Math.PI*120,fg=document.getElementById("fg");fg.style.strokeDasharray=C;fg.style.strokeDashoffset=0;function fmt(s){return String(Math.floor(s/60)).padStart(2,"0")+":"+String(s%60).padStart(2,"0")}function up(){document.getElementById("tm").textContent=fmt(rem);fg.style.strokeDashoffset=C*(1-rem/tot)}function st(){if(run)return;run=true;tid=setInterval(()=>{rem--;up();if(rem<=0){clearInterval(tid);run=false;beep();alert("时间到!")}},1000)}function pa(){clearInterval(tid);run=false}function rs(){pa();rem=tot;up()}function set(s){pa();tot=s;rem=s;up()}function beep(){const ac=new(window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);o.frequency.value=800;g.gain.setValueAtTime(.3,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.5);o.start();o.stop(ac.currentTime+.5)}up();</script></body></html>'
