    '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>轮播图</title><style>*{margin:0;padding:0;box-sizing:border-box}body{display:flex;align-items:center;justify-content:center;min-height:100vh;background:#f0f0f0}.slider{position:relative;width:700px;height:400px;border-radius:12px;overflow:hidden;box-shadow:0 10px 40px rgba(0,0,0,.2)}.slide{position:absolute;width:100%;height:100%;opacity:0;transition:opacity .8s}.slide.act{opacity:1}.slide img{width:100%;height:100%;object-fit:cover}.arr{position:absolute;top:50%;transform:translateY(-50%);width:50px;height:50px;background:rgba(255,255,255,.7);border:none;border-radius:50%;font-size:24px;cursor:pointer;transition:.3s;z-index:10}.arr:hover{background:#fff}.arr.l{left:15px}.arr.r{right:15px}.dots{position:absolute;bottom:20px;left:50%;transform:translateX(-50%);display:flex;gap:10px;z-index:10}.dot{width:12px;height:12px;border-radius:50%;background:rgba(255,255,255,.5);cursor:pointer;transition:.3s}.dot.act{background:#fff;transform:scale(1.2)}</style></head><body><div class="slider" id="s"><button class="arr l" onclick="mv(-1)">‹</button><button class="arr r" onclick="mv(1)">›</button><div class="dots" id="dots"></div></div><script>const imgs=["https://picsum.photos/700/400?random=1","https://picsum.photos/700/400?random=2","https://picsum.photos/700/400?random=3","https://picsum.photos/700/400?random=4","https://picsum.photos/700/400?random=5"];const s=document.getElementById("s"),dots=document.getElementById("dots");let cur=0,tid;imgs.forEach((_,i)=>{const sl=document.createElement("div");sl.className="slide"+(i?"":" act");sl.innerHTML=`<img src="${imgs[i]}" alt="slide${i+1}">`;s.insertBefore(sl,dots);const d=document.createElement("div");d.className="dot"+(i?"":" act");d.onclick=()=>go(i);dots.appendChild(d)});function go(i){s.querySelectorAll(".slide")[cur].classList.remove("act");dots.children[cur].classList.remove("act");cur=(i+imgs.length)%imgs.length;s.querySelectorAll(".slide")[cur].classList.add("act");dots.children[cur].classList.add("act")}function mv(d){go(cur+d);rst()}function auto(){tid=setInterval(()=>go(cur+1),3000)}function rst(){clearInterval(tid);auto()}s.addEventListener("mouseenter",()=>clearInterval(tid));s.addEventListener("mouseleave",auto);auto();</script></body></html>'
